<script>
document.querySelectorAll('form.form-inline').forEach(function(form) {
    var status = form.querySelector('[name="status"]');
    var eta = form.querySelector('[name="eta_minutes"]');
    function updateEta() {
        eta.required = status.value === 'on-the-way';
        eta.disabled = status.value !== 'on-the-way';
        if (status.value === '15-minutes-away') { eta.value = 15; } else if (eta.disabled) { eta.value = ''; }
    }
    status.addEventListener('change', updateEta);
    updateEta();
});
</script>
